    server_name pulse.example;
    location = /healthz {
        return 200 up;
    }
    location ^~ /assets/ {
        alias /srv/pulse/assets/;
    }
    location = / {
        if ($is_mobile) {
            return 302 https://m.pulse.example/;
        }
        proxy_pass http://$pool;
    }
    location / {
        proxy_pass http://$pool;
    }
}

