    if not cands:
        return None
    host = host.lower().split(":")[0]
    for s in cands:
        if host in s.names:
            return s
    best, blen = None, -1
    for s in cands:
        for n in s.names:
            pat = None
            if n.startswith("*."):
                pat = n[1:]
            elif n.startswith("."):
                if host == n[1:]:
                    return s
                pat = n
            if pat and host.endswith(pat) and len(pat) > blen:
                best, blen = s, len(pat)
    if best:
        return best
    for s in cands:
        for n in s.names:
            if n.startswith("~") and re.search(n[1:], host):
