            return l, None
    best = None
    for l in server.locs:
        if l.mod in ("", "^~") and path.startswith(l.pat) and (best is None or len(l.pat) > len(best.pat)):
            best = l
    if best is not None and best.mod == "^~":
        return best, None
    for l in server.locs:
        if l.rx is not None:
            m = l.rx.search(path)
            if m:
