server {
    listen 80;
    server_name photos.example;
    location /media/photos/ {
        alias /srv/photos/;
    }
    location /shots/ {
        add_header X-Legacy 1;
        root /srv/photos;
        rewrite ^/shots/(\d+)\.jpg$ /$1.jpg break;
    }
    location = /photo {
        if ($arg_id !~ "^\d+$") {
            return 400;
        }
        rewrite ^ /media/photos/$arg_id.jpg last;
    }
    location / {
        return 404;
    }
}

